.frame-name span {
  font-weight: 700;
}

span.expander {
  display: inline-block;
  margin-right: 10px;
  cursor: pointer;
  transition: transform 0.33s ease-in-out;
}

.frame.collapsed span.expander {
  transform: rotate(-90deg);
}

.frame-name span.breakable {
  word-break: break-all;
}

.code-snippet-wrapper {
  height: auto;
